// <auto-generated/>
using System;
using Fanex.Security;
using Sunplus.Accounting.Core.Common;
using System.Configuration;
using System.Collections.Generic;
using System.Linq;
using Fanex.Tarus.Admin.Core.Configurations;
using System.Web;

public partial class NapCMS_Redirect : System.Web.UI.Page
{
    protected void Page_Load(object sender, EventArgs e)
    {
        if (Request["napcmskey"] != null && !string.IsNullOrEmpty(Request["napcmskey"]))
        {
            var userName = Cryptography.CfsEnCrypt(AppSession.AccUserName.ToString());
            var onuserId = Cryptography.CfsEnCrypt(AppSession.OnAccId.ToString());

            var accUrlIndentify = Request["napcmskey"];
            var mappingUrlSection = MappingNapCMSUrlSection.Instance.NapCMSUrl;
            string newTab = "newTab=false";
            if (HttpContext.Current.Request.Url.ToString().Contains("blank"))
            {
                newTab = "newTab=true";
            }
            if (mappingUrlSection != null)
            {
                var getMappingConfig = (from m in
                                            mappingUrlSection.Cast<NapCMSUrlElement>().Where(
                                                m => m.AccUrl.ToLower().Equals(accUrlIndentify.ToLower()) && m.Active)
                                        select m);
                if (getMappingConfig != null && getMappingConfig.Count() > 0)
                {
                    var napUrl = getMappingConfig.First().NapUrl;
                    var url = string.Format("{0}?username={1}&onlineUserId={2}&redirectUrl={3}&{4}", NapURL(), userName, onuserId, napUrl, newTab);
                    Response.Redirect(url);
                }
            }
        }
        else
        {
            Response.Redirect("Index.aspx");
        }
    }
	
	private string NapURL()
    {
        Uri uri = HttpContext.Current.Request.Url;        
        return string.Format(ConfigurationManager.AppSettings["NapCMSLoginUrl"], uri.Scheme + Uri.SchemeDelimiter + HttpContext.Current.Request.Headers["Host"].ToString());
    }
}